; snsmat.asm -- chapter 34: row 8, three ways
; generated by gen34.py
        INCLUDE "msx.inc"
        OUTPUT "snsmat.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
byport  EQU VARS                ; row 8, from the ports
bybios  EQU VARS + 1            ; from SNSMAT
bycopy  EQU VARS + 2            ; from NEWKEY
iff     EQU VARS + 3            ; after SNSMAT: 4 if the interrupts are on
; Row 8 of the keyboard read three ways every frame: from the ports, with the
; BIOS's SNSMAT, and from NEWKEY + 8, the copy the BIOS's interrupt keeps.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $80          ; colours  $2000
        VDP_REG 4, $00          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: chapter 30's set at 32
        ld hl, shapes
        ld e, 4
        call send
        VRAM_WRITE $2000        ; black ink on white paper
        ld a, $1F
        ld b, 32
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; the names
        ld hl, names
        ld e, 3
        call send
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        im 1                    ; the interrupt: the BIOS's routine at $0038
        VDP_REG 1, $E0          ; the display on, and the frame's signal
main:   ei
        halt                    ; the frame, and the BIOS's interrupt routine
        di
row8:   in a, (PPI_C)           ; 12  row 8 from the ports
        and $F0                 ;  8
        or 8                    ;  8
        out (PPI_C), a          ; 12
        in a, (PPI_B)           ; 12
        ld (byport), a
bios:   ld a, 8                 ;  8  row 8 from the BIOS
        call SNSMAT             ; 18 + the routine
sbios:  ld (bybios), a
        ld a, i                 ; P/V: the interrupts on or off (chapter 17)
        ld a, 0
        jp po, .off
        ld a, 4
.off:   ld (iff), a
        di
copy:   ld a, (NEWKEY + 8)      ; 14  row 8 from the BIOS's copy
        ld (bycopy), a
stored: ld d, 3
        ld e, 9
        call at
        ld a, (byport)
        call cells
        ld e, 19
        call at
        ld a, (byport)
        call hex
        ld d, 5
        ld e, 9
        call at
        ld a, (bybios)
        call cells
        ld e, 19
        call at
        ld a, (bybios)
        call hex
        ld d, 7
        ld e, 9
        call at
        ld a, (bycopy)
        call cells
        ld e, 19
        call at
        ld a, (bycopy)
        call hex
        jr main

; at: the next characters go to row D, column E (chapter 30)
at:     ld a, d
        rrca
        rrca
        rrca
        ld c, a
        and $E0
        or e
        out (VDP_CTRL), a
        ld a, c
        and $03
        or $18 | $40
        out (VDP_CTRL), a
        ret

; cells: A as eight boxes from bit 7, a filled box for a 0 (a key held) and
; an empty one for a 1, from the address set. Uses A, B, L
cells:  ld l, a
        ld b, 8
.cell:  ld a, 2
        rlc l                   ; the next bit, into the carry
        jr nc, .put             ; 0: held
        ld a, 1
.put:   out (VDP_DATA), a
        djnz .cell
        ret

; hex: A as two hexadecimal digits, from the address set. Uses A, C
hex:    ld c, a
        rrca
        rrca
        rrca
        rrca
        call .digit
        ld a, c
.digit: and $0F
        add a, '0'
        cp '9' + 1
        jr c, .out
        add a, 'A' - '9' - 1
.out:   out (VDP_DATA), a
        ret

; send: E blocks of 256 bytes from HL to the VDP
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret
